<script setup lang="ts">
import {onMounted,ref,watch} from 'vue'
import {httpClient} from '@/shared/http/client'
import {mapStatus} from './map-recommendation'
const props=defineProps<{caseId?:string;selectedShopId?:number;initialAddress?:string}>()
const emit=defineEmits<{choose:[value:{shopId:number;queryId:string;name:string}|undefined];pending:[value:boolean];confirmed:[value:{districtId:number;address:string}]}>()
interface Region {id:number;name:string;adcode:string}
interface Candidate {token:string;address:string;province:string;city:string;district:string;adcode:string;level:string;status:string;mock:boolean;point:{longitude:number;latitude:number}}
interface ShopRow {shopId:number;name:string;address:string;qualification:string;status:string;metres:number|null;seconds:number|null;calculatedAt:string|null;mock:boolean}
interface Recommendation {queryId:string;provider:string;mock:boolean;scope:string;complete:boolean;expiresAt:string;shops:{page:number;size:number;total:number;records:ShopRow[]}}
interface Exclusion {id:number;name:string;address:string;status:string}
const cities=ref<Region[]>([]),districts=ref<Region[]>([]),city=ref(''),district=ref(''),detail=ref(props.initialAddress??''),candidates=ref<Candidate[]>([]),confirmed=ref<Candidate>(),error=ref(''),busy=ref(false),cityPage=ref(1),districtPage=ref(1),cityTotal=ref(0),districtTotal=ref(0)
const budget=ref<{callsEnabled:boolean;reason:string}>()
async function loadBudget(){try{budget.value=(await httpClient.get('/maps/locations/budget')).data.data}catch(e){budget.value={callsEnabled:false,reason:'无法确认地图调用状态，请刷新服务状态'};error.value=e instanceof Error?e.message:'服务状态读取失败'}}
let generation=0
const shopCity=ref(''),recommendation=ref<Recommendation>(),exclusions=ref<Exclusion[]>([]),excludedPage=ref(1),excludedTotal=ref(0)
const context=ref<{accidentRegion:string;vehicleBrand:string;vehicleModel:string}>()
let queryKey='',queryIdentity=''
function clearRecommendation(){emit('pending',true);recommendation.value=undefined;exclusions.value=[];excludedPage.value=1;excludedTotal.value=0;emit('choose',undefined)}
async function regions(kind:'city'|'district'){
  if(busy.value)return
  busy.value=true;error.value='';const requestedCity=city.value
  try{const page=kind==='city'?cityPage.value:districtPage.value;const response=(await httpClient.get('/maps/locations/regions',{params:{page,size:20,...(kind==='district'?{cityId:Number(city.value)}:{})}})).data.data as {total:number;records:Region[]}
    if(kind==='district'&&requestedCity!==city.value)return
    if(kind==='city'){cities.value.push(...response.records);cityTotal.value=response.total;cityPage.value++}else{districts.value.push(...response.records);districtTotal.value=response.total;districtPage.value++}
  }catch(e){error.value=e instanceof Error?e.message:'区域加载失败'}finally{busy.value=false}
}
watch(city,async()=>{generation++;district.value='';districts.value=[];districtPage.value=1;districtTotal.value=0;if(city.value)await regions('district')})
watch([city,district,detail],()=>{generation++;confirmed.value=undefined;candidates.value=[];clearRecommendation()})
watch(shopCity,clearRecommendation)
async function resolve(){
  if(busy.value||budget.value?.callsEnabled===false||!district.value||detail.value.trim().length<4)return
  busy.value=true;error.value='';confirmed.value=undefined;candidates.value=[];const requestGeneration=generation
  try{const response=(await httpClient.post('/maps/locations/resolve',{districtId:Number(district.value),detail:detail.value.trim()})).data.data as {token:string;candidate:Candidate}[];if(requestGeneration===generation)candidates.value=response.map(item=>({...item.candidate,token:item.token}))}
  catch(e){error.value=e instanceof Error?e.message:'地址解析失败，未自动重试'}finally{busy.value=false}
}
async function confirm(item:Candidate){if(busy.value)return;busy.value=true;error.value='';try{await httpClient.post(`/maps/locations/${item.token}/confirm`);confirmed.value=item;clearRecommendation();const selectedCity=cities.value.find(row=>String(row.id)===city.value);const selectedDistrict=districts.value.find(row=>String(row.id)===district.value);emit('confirmed',{districtId:Number(district.value),address:`广东省${selectedCity?.name??''}${selectedDistrict?.name??''}${detail.value.trim()}`})}catch(e){error.value=e instanceof Error?e.message:'位置确认失败'}finally{busy.value=false}}
async function excluded(page=1){if(!props.caseId)return;const value=(await httpClient.get(`/maps/cases/${props.caseId}/recommendation-exclusions`,{params:{page,size:20,shopCityId:shopCity.value?Number(shopCity.value):undefined}})).data.data as {total:number;records:Exclusion[]};exclusions.value=value.records;excludedPage.value=page;excludedTotal.value=value.total}
async function query(fresh=false){
  if(busy.value||budget.value?.callsEnabled===false||!confirmed.value||!props.caseId)return
  busy.value=true;error.value='';emit('choose',undefined)
  const identity=`${confirmed.value.token}:${shopCity.value}`
  if(fresh||identity!==queryIdentity||!queryKey){queryKey=crypto.randomUUID();queryIdentity=identity}
  try{recommendation.value=(await httpClient.post(`/maps/cases/${props.caseId}/recommendations`,{locationToken:confirmed.value.token,shopCityId:shopCity.value?Number(shopCity.value):null},{timeout:75000,headers:{'Idempotency-Key':queryKey}})).data.data as Recommendation;const nearest=recommendation.value.shops.records.find(row=>row.status==='READY'&&row.metres!=null);if(nearest)emit('choose',{shopId:nearest.shopId,queryId:recommendation.value.queryId,name:nearest.name});await excluded();await loadBudget()}
  catch(e){error.value=e instanceof Error?e.message:'附近网点查询失败，未自动重试'}finally{busy.value=false}
}
async function resultPage(page:number){if(!recommendation.value||busy.value)return;busy.value=true;error.value='';try{recommendation.value=(await httpClient.get(`/maps/recommendations/${recommendation.value.queryId}`,{params:{page,size:20}})).data.data as Recommendation}catch(e){error.value=e instanceof Error?e.message:'分页读取失败'}finally{busy.value=false}}
async function excludedPageChange(page:number){if(busy.value)return;busy.value=true;error.value='';try{await excluded(page)}catch(e){error.value=e instanceof Error?e.message:'资料提示加载失败'}finally{busy.value=false}}
onMounted(async()=>{await loadBudget();await regions('city');if(props.caseId)try{context.value=(await httpClient.get(`/maps/cases/${props.caseId}/recommendation-context`)).data.data}catch(e){error.value=e instanceof Error?e.message:'案件资格上下文加载失败'}})
</script>
<template>
<section class="parking dispatch-location" data-reading="定位与推荐">
 <header><div><span class="eyebrow">LOCATION / DISPATCH</span><h3>定位接车位置</h3></div><span class="provider-badge">定位服务</span></header>
 <div class="service-state"><p v-if="budget?.callsEnabled===false" role="status">{{ budget.reason }}。可查看已有结果，不会自动调用高德。</p><button class="text-button" type="button" :disabled="busy" @click="loadBudget">刷新地图服务状态（不新增地图调用）</button></div>
 <details class="location-help"><summary>定位与服务范围说明</summary><p>事故区域决定服务资格；这里填写车辆现在的位置，仅用于“车辆→网点”的送店距离，不是上门接车距离，不修改事故地址。</p><p v-if="context">案件事故区域：{{ context.accidentRegion }} · 车型：{{ context.vehicleBrand }} / {{ context.vehicleModel }}。下方为独立的车辆当前停放位置。</p><p role="note">名称含【测试／非真实合作方】的网点仅供联调，不代表真实合作关系或维修能力。</p></details>
 <fieldset class="location-fields" :disabled="busy">
  <div class="region-field"><span class="field-label">城市 / 区县 <small>广东省</small></span><div class="region-selects"><label class="sr-only" for="parking-city">车辆停放城市</label><select id="parking-city" v-model="city" aria-label="车辆停放城市"><option value="">请选择城市</option><option v-for="item in cities" :key="item.id" :value="String(item.id)">{{ item.name }}</option></select><label class="sr-only" for="parking-district">车辆停放区县</label><select id="parking-district" v-model="district" aria-label="车辆停放区县"><option value="">请选择区县</option><option v-for="item in districts" :key="item.id" :value="String(item.id)">{{ item.name }}</option></select></div><div class="region-more"><button v-if="cities.length<cityTotal" class="text-button" type="button" @click="regions('city')">加载更多城市</button><button v-if="districts.length<districtTotal" class="text-button" type="button" @click="regions('district')">加载更多区县</button></div></div>
  <label>接车地址<input v-model="detail" maxlength="200" aria-label="车辆停放详细地址" placeholder="街道、门牌或明确地标"></label>
 </fieldset>
 <div class="locate-actions"><span class="action-hint">解析后，请核对候选位置再确认</span><button class="locate-button" type="button" :disabled="budget?.callsEnabled===false||busy||!district||detail.trim().length<4" @click="resolve">{{ busy?'地址解析中…':'解析停放位置' }}</button></div>
 <p v-if="error" role="alert" class="error">{{ error }}</p><p v-if="!busy&&cities.length===0" class="empty">尚未配置启用的广东行政区域，请管理员维护；不会用城市中心代替车辆位置。</p>
 <ul v-if="candidates.length" class="location-candidates"><li v-for="(item,index) in candidates" :key="index"><div><strong>{{ item.address }}</strong><small>{{ item.province }} / {{ item.city }} / {{ item.district }} · {{ item.adcode }} · 匹配级别：{{ item.level }}</small></div><button v-if="item.status==='REQUIRES_CONFIRMATION'" :data-location-token="item.token" type="button" :disabled="busy" @click="confirm(item)">确认这是当前车辆停放位置{{ item.mock?'（Mock合成）':'' }}</button><span v-else>{{ item.status==='REGION_MISMATCH'?'与所选广东城市/区县不符，不能使用':'定位过粗，请补充详细地址' }}</span></li></ul>
 <p v-if="confirmed" role="status" class="confirmed-label">已确认：{{ confirmed.address }}（修改地址即失效，确认最多保留10分钟）</p>
 <div class="map-surface"><div class="map-caption"><span>{{ confirmed?'已确认车辆停放位置':'先选择城市并定位' }}</span><span>位置示意 · 非高德底图 / 道路</span></div><svg viewBox="0 0 600 320" role="img" aria-label="停车位置示意图，不展示未经核实的网点坐标或道路路线"><defs><pattern id="parking-dispatch-grid" width="40" height="40" patternUnits="userSpaceOnUse"><path d="M40 0H0V40" fill="none" stroke="#cedfd7" stroke-width="1"/></pattern></defs><rect width="600" height="320" fill="#edf3ed"/><rect width="600" height="320" fill="url(#parking-dispatch-grid)"/><path d="M-20 235C90 100 180 270 310 130S510 130 640-30" fill="none" stroke="#c1dedf" stroke-width="32"/><path d="M-20 90L620 250M100-20L430 340M-20 280L600 40" fill="none" stroke="#fffdf7" stroke-width="13"/><path d="M-20 90L620 250M100-20L430 340M-20 280L600 40" fill="none" stroke="#dbe2d5" stroke-width="1"/><g v-if="confirmed"><circle cx="300" cy="160" r="12" fill="#e39e58" stroke="#fff" stroke-width="3"/><text x="300" y="132" text-anchor="middle" fill="#58452f" font-size="14">已确认接车位置</text><text x="300" y="198" text-anchor="middle" fill="#61756b" font-size="12">网点距离与选择见下方列表</text></g><text v-else x="300" y="166" text-anchor="middle" fill="#61756b" font-size="14">定位并确认后查看附近合作网点</text></svg></div>
 <div class="recommend-heading"><h4>合作网点 <span>{{ recommendation?.shops.total??0 }}</span></h4><small>{{ !recommendation?'定位确认后查询道路距离':recommendation.mock?'Mock演示，不提供真实道路距离':recommendation.complete?'按高德驾车距离排序，可手动改选':'部分距离未知，请人工核对' }}</small></div>
 <div class="recommend-actions"><label>网点所在城市<select v-model="shopCity" :disabled="busy" aria-label="推荐网点所在城市"><option value="">全部广东合作网点</option><option v-for="item in cities" :key="item.id" :value="String(item.id)">{{ item.name }}</option></select></label><button class="locate-button" type="button" :disabled="budget?.callsEnabled===false||busy||!confirmed||!props.caseId" @click="query(false)">{{ busy?'查询中，请稍候…':'查询附近可服务网点' }}</button></div>
 <button v-if="recommendation||error" class="text-button" type="button" :disabled="budget?.callsEnabled===false||busy||!confirmed" @click="query(true)">明确重新计算（可能新增调用量）</button>
 <template v-if="recommendation"><div class="shop-list" aria-label="合作网点候选"><button v-for="(item,index) in recommendation.shops.records" :key="item.shopId" :aria-pressed="props.selectedShopId===item.shopId" :class="{selected:props.selectedShopId===item.shopId}" :disabled="busy||item.status!=='READY'" type="button" @click="emit('choose',{shopId:item.shopId,queryId:recommendation.queryId,name:item.name})"><span class="shop-number">{{ (recommendation.shops.page-1)*20+index+1 }}</span><span class="shop-name">{{ item.name }}<small>{{ item.address }}</small><small>{{ item.qualification }} · {{ mapStatus(item.status) }}</small></span><span class="shop-distance">{{ item.metres==null?'距离未知':`${(item.metres/1000).toFixed(2)} km` }}<small>{{ item.seconds==null?'':`约${Math.ceil(item.seconds/60)}分钟` }}</small></span></button></div><p v-if="recommendation.shops.total===0" class="empty">没有符合事故区域、启用、车型及省内位置条件的网点，请先核对事故区县及网点资料。</p><p v-if="recommendation.shops.records.find(item=>item.shopId===props.selectedShopId)" class="selected-label">已选网点：{{ recommendation.shops.records.find(item=>item.shopId===props.selectedShopId)?.name }}</p>
 <div v-if="recommendation.shops.total>20" class="pagination"><button type="button" :disabled="busy||recommendation.shops.page<=1" @click="resultPage(recommendation.shops.page-1)">上一页</button><span>第{{ recommendation.shops.page }}页，共{{ recommendation.shops.total }}个</span><button type="button" :disabled="busy||recommendation.shops.page*20>=recommendation.shops.total" @click="resultPage(recommendation.shops.page+1)">下一页</button></div>
 <details class="result-details"><summary>距离计算与资格详情</summary><p>{{ recommendation.mock?'Mock演示：不提供真实道路距离':'高德地图驾车规划v5 · 策略32（高德推荐）' }} · 车辆→网点。按主方案道路距离排序，不是理论最短距离、实际里程、骑行距离或拖车报价。</p><p>覆盖：{{ recommendation.scope }}。全部候选计算后分页；{{ recommendation.complete?'距离计算完成':'部分或全部距离未知，未完成全体真实距离排序' }}。推荐有效至 {{ new Date(recommendation.expiresAt).toLocaleTimeString() }}。</p><p v-for="item in recommendation.shops.records" :key="item.shopId">{{ item.name }} · {{ mapStatus(item.status) }} · {{ item.calculatedAt?new Date(item.calculatedAt).toLocaleString():'尚无计算时间' }}</p><p>选择只填入原派单控件，仍需点击原派单/改派按钮；提交时重新校验资格。距离未知可人工处理，不会自动派单。</p></details>
 <details v-if="excludedTotal" class="result-details"><summary>未进入推荐的资料提示（{{ excludedTotal }}个）</summary><p v-for="item in exclusions" :key="item.id">{{ item.name }}：{{ mapStatus(item.status) }}</p><button :disabled="busy||excludedPage<=1" @click="excludedPageChange(excludedPage-1)">上一页</button><button :disabled="busy||excludedPage*20>=excludedTotal" @click="excludedPageChange(excludedPage+1)">下一页</button></details></template>
 <small class="map-note">示意区不提供可点击选点或道路导航；距离来源与计算状态见下方列表，原人工派单入口保留。</small>
</section></template>
<style scoped>
