tween;gap:12px;padding:12px 14px;background:#f9fcf6e8;font-size:11px;color:#4b6356}.map-caption span:last-child{color:#718379}.map-surface svg{display:block;width:100%;max-height:330px}.recommend-heading{display:flex;justify-content:space-between;align-items:center;gap:12px;margin:20px 0 12px}.recommend-heading h4{margin:0;font-size:15px}.recommend-heading h4 span{margin-left:6px;font-size:12px;color:#6b7d74}.recommend-heading small,.map-note{font-size:11px;color:#6a7d72}.recommend-actions label{display:grid;gap:6px;font-size:12px;max-width:50%}.shop-list{display:grid;grid-template-columns:1fr 1fr;gap:8px;max-height:290px;overflow-y:auto;padding:2px}.shop-list button{display:flex;gap:9px;align-items:center;text-align:left;background:#fff!important;border-color:#d7e2da!important;padding:12px!important;min-width:0}.shop-list button.selected{background:#eff8f0!important;border-color:#44745a!important}.shop-number{font-size:11px;min-width:20px;color:#6b7d74}.shop-name{font-size:12px;line-height:1.5;flex:1;overflow-wrap:anywhere}.shop-name small{display:block;color:#61766a;font-size:10px;margin-top:4px}.shop-distance{font-size:11px;white-space:nowrap;color:#61766a}.shop-distance small{display:block;font-size:10px;margin-top:4px}.selected-label,.confirmed-label{font-size:12px;padding:12px 0 0;color:#2f6145}.confirmed-label{padding:0}.map-note{display:block;margin-top:14px}.error{color:#a7313c;font-size:12px}.empty{font-size:12px;color:#687a70}.text-button{font-size:12px!important}.pagination{display:flex;justify-content:space-between;align-items:center;gap:12px;margin-top:10px;font-size:12px}.sr-only{position:absolute;width:1px;height:1px;padding:0;margin:-1px;overflow:hidden;clip:rect(0,0,0,0);white-space:nowrap;border:0}@media(max-width:680px){.location-fields,.shop-list{grid-template-columns:1fr}.map-caption,.recommend-heading{align-items:flex-start;flex-direction:column}.locate-actions,.recommend-actions,.location-candidates li{align-items:flex-start;flex-direction:column}.recommend-actions label{max-width:none;width:100%}}
</style>
